test "$(find /var/lib/rkuarch -maxdepth 0 -perm /022 -print)" = ""
test -d /var/lib/rkuarch/k2
test ! -L /var/lib/rkuarch/k2
test "$(stat -c %u /var/lib/rkuarch/k2)" = 0
test "$(find /var/lib/rkuarch/k2 -maxdepth 0 -perm /022 -print)" = ""
test -d /var/lib/rkuarch/k2/candidate-04-combined-runtime-v2
